// Supabase (service role) implementations of PrincipalStore and
// PortalInviteStore. The has_* columns are generated by Postgres and never
// written; restricted columns are checked to be sealed before every write.

import type { SupabaseClient } from "@supabase/supabase-js";
import { assertSealed, PrincipalConcurrencyError, type PortalInvite, type PortalInviteStore, type PrincipalStore, type PrincipalUpdate } from "./store";
import type { PrincipalRow } from "./types";

type Row = Record<string, unknown>;

function fail(what: string, error: { message: string }): never {
  throw new Error(`${what}: ${error.message}`);
}

const COLUMNS: Partial<Record<keyof PrincipalRow, string>> = {
  id: "id",
  dealId: "deal_id",
  leadId: "lead_id",
  parentId: "parent_id",
  kind: "kind",
  legalName: "legal_name",
  roles: "roles",
  title: "title",
  ownershipPct: "ownership_pct",
  isGuarantor: "is_guarantor",
  email: "email",
  phone: "phone",
  homeAddress: "home_address",
  formationState: "formation_state",
  citizenship: "citizenship",
  reoSchedule: "reo_schedule",
  hud2530: "hud_2530",
  creditAuthorization: "credit_authorization",
  pfsAsOf: "pfs_as_of",
  taxIdIndex: "tax_id_index",
  ssnEnc: "ssn",
  dobEnc: "dob",
  pfsEnc: "pfs",
  form1919Enc: "form_1919",
};

/** Writable columns only (generated has_* flags and timestamps are excluded). */
export function principalToRow(p: Partial<PrincipalRow>): Row {
  const out: Row = {};
  for (const [k, col] of Object.entries(COLUMNS)) {
    const v = p[k as keyof PrincipalRow];
    if (v !== undefined) out[col!] = v;
  }
  return out;
}

export function principalFromRow(r: Row): PrincipalRow {
  const out: Record<string, unknown> = {};
  for (const [k, col] of Object.entries(COLUMNS)) out[k] = r[col!] ?? null;
  out.roles = (r.roles as string[] | null) ?? [];
  out.ownershipPct = r.ownership_pct === null || r.ownership_pct === undefined ? null : Number(r.ownership_pct);
  out.isGuarantor = r.is_guarantor === true;
  out.hasSsn = r.has_ssn === true;
  out.hasDob = r.has_dob === true;
  out.hasPfs = r.has_pfs === true;
  out.hasForm1919 = r.has_form_1919 === true;
  out.version = Number(r.version);
  out.createdAt = String(r.created_at);
  out.updatedAt = String(r.updated_at);
  return out as PrincipalRow;
}

export function supabasePrincipalStore(db: SupabaseClient): PrincipalStore {
  return {
    async insert(row, now) {
      assertSealed(row);
      const ts = now.toISOString();
      const { data, error } = await db.from("principals").insert({ ...principalToRow(row), created_at: ts, updated_at: ts }).select("*").single();
      if (error) fail("principal insert failed", error);
      return principalFromRow(data as Row);
    },
    async get(id) {
      const { data, error } = await db.from("principals").select("*").eq("id", id).maybeSingle();
      if (error) fail("principal lookup failed", error);
      return data ? principalFromRow(data as Row) : null;
    },
    async forDeal(dealId) {
      const { data, error } = await db.from("principals").select("*").eq("deal_id", dealId).order("created_at").limit(500);
      if (error) fail("principal list failed", error);
      return (data ?? []).map((r) => principalFromRow(r as Row));
    },
    async update(id, expectedVersion, patch: PrincipalUpdate, now) {
      assertSealed(patch);
      const { data, error } = await db
        .from("principals")
        .update({ ...principalToRow(patch), version: expectedVersion + 1, updated_at: now.toISOString() })
        .eq("id", id)
        .eq("version", expectedVersion)
        .select("*")
        .maybeSingle();
      if (error) fail("principal update failed", error);
      if (!data) throw new PrincipalConcurrencyError();
      return principalFromRow(data as Row);
    },
    async remove(id) {
      const { error } = await db.from("principals").delete().eq("id", id);
      if (error) fail("principal delete failed", error);
    },
    async findByTaxIdIndex(index) {
      const { data, error } = await db.from("principals").select("id, deal_id, legal_name").eq("tax_id_index", index).limit(50);
      if (error) fail("principal duplicate lookup failed", error);
      return (data ?? []).map((r) => ({ id: String((r as Row).id), dealId: String((r as Row).deal_id), legalName: String((r as Row).legal_name) }));
    },
  };
}

export function inviteFromRow(r: Row): PortalInvite {
  return {
    id: String(r.id),
    dealId: String(r.deal_id),
    principalId: (r.principal_id as string | null) ?? null,
    email: String(r.email),
    tokenHash: String(r.token_hash),
    expiresAt: new Date(String(r.expires_at)).toISOString(),
    consumedAt: r.consumed_at ? new Date(String(r.consumed_at)).toISOString() : null,
    revokedAt: r.revoked_at ? new Date(String(r.revoked_at)).toISOString() : null,
    sessionExpiresAt: r.session_expires_at ? new Date(String(r.session_expires_at)).toISOString() : null,
    createdBy: String(r.created_by),
    createdAt: new Date(String(r.created_at)).toISOString(),
  };
}

export function supabasePortalInviteStore(db: SupabaseClient): PortalInviteStore {
  return {
    async insert(invite, now) {
      const { data, error } = await db
        .from("portal_invites")
        .insert({ deal_id: invite.dealId, principal_id: invite.principalId, email: invite.email, token_hash: invite.tokenHash, expires_at: invite.expiresAt, created_by: invite.createdBy, created_at: now.toISOString() })
        .select("*")
        .single();
      if (error) fail("portal invite insert failed", error);
      return inviteFromRow(data as Row);
    },
    async get(id) {
      const { data, error } = await db.from("portal_invites").select("*").eq("id", id).maybeSingle();
      if (error) fail("portal invite lookup failed", error);
      return data ? inviteFromRow(data as Row) : null;
    },
    async getByTokenHash(tokenHash) {
      const { data, error } = await db.from("portal_invites").select("*").eq("token_hash", tokenHash).maybeSingle();
      if (error) fail("portal invite lookup failed", error);
      return data ? inviteFromRow(data as Row) : null;
    },
    async consume(id, sessionExpiresAt, now) {
      // Conditional update: only one redemption can win.
      const { data, error } = await db
        .from("portal_invites")
        .update({ consumed_at: now.toISOString(), session_expires_at: sessionExpiresAt })
        .eq("id", id)
        .is("consumed_at", null)
        .is("revoked_at", null)
        .select("*")
        .maybeSingle();
      if (error) fail("portal invite redeem failed", error);
      return data ? inviteFromRow(data as Row) : null;
    },
    async revoke(id, now) {
      const { error } = await db.from("portal_invites").update({ revoked_at: now.toISOString() }).eq("id", id).is("revoked_at", null);
      if (error) fail("portal invite revoke failed", error);
    },
    async forDeal(dealId) {
      const { data, error } = await db.from("portal_invites").select("*").eq("deal_id", dealId).order("created_at", { ascending: false }).limit(100);
      if (error) fail("portal invite list failed", error);
      return (data ?? []).map((r) => inviteFromRow(r as Row));
    },
  };
}
